[{"type":"code"}]},{"type":"text","text":". String literals use "},{"type":"text","text":"single","marks":[{"type":"bold"}]},{"type":"text","text":" quotes: "},{"type":"text","text":"''Mumbai''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"7e000ba1-f2f0-7f68-8550-95ce9dbf12cb","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between SQL and MySQL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SQL is the "},{"type":"text","text":"language","marks":[{"type":"italic"}]},{"type":"text","text":" (an ISO standard). MySQL is one "},{"type":"text","text":"database product","marks":[{"type":"italic"}]},{"type":"text","text":" (an RDBMS) that implements SQL with its own extensions — like PostgreSQL, SQL Server, Oracle and SQLite."}]}]}},"revision":1},{"id":"7ffd3d3f-b1a6-7470-ba94-2f404e54b7aa","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does “declarative” mean for SQL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You describe the result set you want, not the algorithm. The optimizer chooses the execution plan (index vs full scan, join order, hash vs nested-loop join), so the same query can get faster when indexes are added without changing a line of SQL."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
