216-8eb1-122eebf8e7e6","type":"code","position":"aC","content":{"language":"text","code":"with_pipe  | with_concat | with_separator | formatted\n-----------+-------------+----------------+----------------\nNeha (n/a) | Neha - 2    | Neha, 2        | Neha  |   72000\nDev (n/a)  | Dev -       | Dev            | Dev   |   60000","filename":"Output"},"revision":1},{"id":"c9d607e7-a753-7612-92f1-979b7853671d","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"||","marks":[{"type":"code"}]},{"type":"text","text":" with a "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" operand gives "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" (see Neha''s email handled with "},{"type":"text","text":"COALESCE","marks":[{"type":"code"}]},{"type":"text","text":"). "},{"type":"text","text":"concat()","marks":[{"type":"code"}]},{"type":"text","text":" treats "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" as an empty string in SQLite, PostgreSQL and SQL Server — but in "},{"type":"text","text":"MySQL","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"CONCAT()","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" if any argument is "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"concat_ws","marks":[{"type":"code"}]},{"type":"text","text":" skips "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s everywhere (Dev''s missing email and department vanish)."}]}]}},"revision":1},{"id":"fcd85181-5531-79a2-af7c-3296dce6871d","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Aggregating strings"}]},"revision":1},{"id":"e3490142-bee9-72d4-8ab3-21b157b7521c","type":"code","position":"aF","content":{"language":"sql","code":"SELECT dept_id,\n       group_concat(name, '', '' ORDER BY name) AS team\nFROM employees\nWHERE dept_id IS NOT NULL\nGROUP BY dept_id\nORDER BY dept_id;","filename":"SQL"},"revision":1},{"id":"ad66c735-2cac-7b67-bfbe-ed9cdd201393","type":"code","position":"aG","content":{"language":"text","code":"dept_id | team\n--------+-------------------------\n1       | Asha, Karan, Meera, Ravi\n2       | Arjun, Neha, Priya\n3       | Sara, Vikram","filename":"Output"},"revision":1},{"id":"ddfe7e79-a9f3-73e0-8c6c-3cbc63ac6ab6","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spellings: "},{"type":"text","text":"STRING_AGG(name, '', '' ORDER BY name)","marks":[{"type":"code"}]},{"type":"text","text":" (PostgreSQL, SQLite 3.44+), "},{"type":"text","text":"STRING_AGG(name, '', '') WITHIN GROUP (ORDER BY name)","marks":[{"type":"code"}]},{"type":"text","text":" (SQL Server), "},{"type":"text","text":"GROUP_CONCAT(name ORDER BY name SEPARATOR '', '')","marks":[{"type":"code"}]},{"type":"text","text":" (MySQL), "},{"type":"text","text":"LISTAGG(name, '', '') WITHIN GROUP (ORDER BY name)","marks":[{"type":"code"}]},{"type":"text","text":" (Oracle)."}]}]}},"revision":1},{"id":"081e93df-06e7-770e-8d8b-a3dea6579b93","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you extract the domain from an email in SQL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the "},{"type":"text","text":"@","marks":[{"type":"code"}]},{"type":"text","text":" and take everything after it: "},{"type":"text","text":"substr(email, instr(email, ''@'') + 1)","marks":[{"type":"code"}]},{"type":"text","text":" (SQLite/MySQL), "},{"type":"text","text":"SUBSTRING(email, CHARINDEX(''@'', email) + 1, LEN(email))","marks":[{"type":"code"}]},{"type":"text","text":" (SQL Server), "},{"type":"text","text":"split_part(email, ''@'', 2)","marks":[{"type":"code"}]},{"type":"text","text":" (PostgreSQL), "},{"type":"text","text":"SUBSTRING_INDEX(email, ''@'', -1)","marks":[{"type":"code"}]},{"type":"text","text":" (MySQL)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
