SELECT '7e450292-a129-7cf8-ad68-7f8a4916a2a4', '31a6ec8f-36b4-7663-a454-ea454751ae6b', 1, 'PUBLISHED', 'Transactions & ACID', '[{"id":"64a08764-374f-7d07-83a7-abff71132692","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A transaction groups several statements into one unit of work that either "},{"type":"text","text":"fully happens or not at all","marks":[{"type":"bold"}]},{"type":"text","text":". It is what makes a money transfer safe."}]}]}},"revision":1},{"id":"e310c270-6d83-74c4-9c03-7a847fd2141f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"ACID"}]},"revision":1},{"id":"13a9422d-28af-7104-9e1b-864a7df7c920","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Property"}],[{"type":"text","text":"Guarantee"}],[{"type":"text","text":"Mechanism"}]],[[{"type":"text","text":"Atomicity","marks":[{"type":"bold"}]}],[{"type":"text","text":"All statements succeed, or none take effect"}],[{"type":"text","text":"Undo/rollback log"}]],[[{"type":"text","text":"Consistency","marks":[{"type":"bold"}]}],[{"type":"text","text":"Each transaction moves the DB from one valid state to another (constraints hold)"}],[{"type":"text","text":"Constraints, triggers, your logic"}]],[[{"type":"text","text":"Isolation","marks":[{"type":"bold"}]}],[{"type":"text","text":"Concurrent transactions don''t see each other''s partial work (to a chosen degree)"}],[{"type":"text","text":"Locks and/or MVCC snapshots"}]],[[{"type":"text","text":"Durability","marks":[{"type":"bold"}]}],[{"type":"text","text":"Once committed, changes survive crashes and power loss"}],[{"type":"text","text":"Write-ahead log (WAL) flushed to disk"}]]]},"revision":1},{"id":"b2421e5a-b40a-71f6-b594-3bb7d56bbb62","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"BEGIN, COMMIT, ROLLBACK"}]},"revision":1},{"id":"a1d465f4-6ba1-7fbf-a8b0-4c31805f016a","type":"code","position":"a4","content":{"language":"sql","code":"BEGIN;\nUPDATE accounts SET balance = balance - 200 WHERE id = 1;\nUPDATE accounts SET balance = balance + 200 WHERE id = 2;\nCOMMIT;\n\nSELECT * FROM accounts ORDER BY id;","filename":"SQL"},"revision":1},{"id":"01010cdb-c96a-7651-85b4-97531336094a","type":"code","position":"a5","content":{"language":"text","code":"id | owner | balance\n---+-------+--------\n1  | Asha  | 800\n2  | Ravi  | 700","filename":"Output"},"revision":1},{"id":"4630cdac-ec58-72e2-b9f3-20afb8182b6d","type":"code","position":"a6","content":{"language":"sql","code":"BEGIN;\nUPDATE accounts SET balance = balance - 200 WHERE id = 1;\n-- …the app detects a problem before crediting Ravi\nROLLBACK;\n\nSELECT * FROM accounts ORDER BY id;","filename":"SQL"},"revision":1},{"id":"3fe52ee2-2f1e-7acf-9b15-3fe55fc7053a","type":"code","position":"a7","content":{"language":"text","code":"id | owner | balance\n---+-------+--------\n1  | Asha  | 1000\n2  | Ravi  | 500","filename":"Output"},"revision":1},{"id":"2e818980-f214-7e75-b616-a93849fc82e3","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"When a statement fails"}]},"revision":1},{"id":"e4eb73f9-9a98-76c6-bb41-10beb75f4731","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A transfer of 1500 breaks the "},{"type":"text","text":"CHECK (balance >= 0)","marks":[{"type":"code"}]},{"type":"text","text":" constraint on the debit:"}]}]}},"revision":1},{"id":"d09e9aa3-a833-75bf-a090-0bb53bdcd9e0","type":"code","position":"aA","content":{"language":"sql","code":"BEGIN;\nUPDATE accounts SET balance = balance + 1500 WHERE id = 2;   -- credit first\nUPDATE accounts SET balance = balance - 1500 WHERE id = 1;   -- fails\nCOMMIT;","filename":"SQL"},"revision":1},{"id":"7d9c204a-d150-7070-b5b1-b67c4ee35632","type":"code","position":"aB","content":{"language":"text","code":"CHECK constraint failed: balance >= 0","filename":"Error"},"revision":1},{"id":"4b0fe5a2-702a-7f41-97cb-ff3c5a964713","type":"callout","position":"aC","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In most engines, only the "},{"type":"text","text":"failing statement","marks":[{"type":"bold"}]},{"type":"text","text":" is undone automatically — the earlier credit is still pending inside the open transaction. The application must catch the error and issue "},{"type":"text","text":"ROLLBACK","marks":[{"type":"code"}]},{"type":"text","text":" (PostgreSQL goes further: the whole transaction is marked aborted and only "},{"type":"text","text":"ROLLBACK","marks":[{"type":"code"}]},{"type":"text","text":" is accepted). Drivers and ORMs usually wrap this in a "},{"type":"text","text":"with transaction:","marks":[{"type":"code"}]},{"type":"text","text":" block."}]}]}},"revision":1},{"id":"7b0596d6-9cfd-7e70-91fb-19d8abbccf3b","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Savepoints: partial rollback"}]},"revision":1},{"id":"90994812-e740-766d-8b76-7393f51e58e2","type":"code","position":"aE","content":{"language":"sql","code":"BEGIN;\nINSERT INTO accounts VALUES (3, ''Meera'', 300);\nSAVEPOINT before_bonus;\nUPDATE accounts SET balance = balance + 10000 WHERE id = 3;   -- mistake\nROLLBACK TO before_bonus;                                     -- undo only the bonus\nCOMMIT;\n\nSELECT * FROM accounts ORDER BY id;","filename":"SQL"},"revision":1},{"id":"08bdf531-a72f-7182-966b-19bd6335bc63","type":"code","position":"aF","content":{"language":"text","code":"id | owner | balance\n---+-------+--------\n1  | Asha  | 1000\n2  | Ravi  | 500\n3  | Meera | 300","filename":"Output"},"revision":1},{"id":"860ed4b7-40de-7ac1-9fb3-571b9bd76ee1","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Autocommit"}]},"revision":1},{"id":"66dc1509-0a30-7179-bd71-f7b301dd4ce7","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Outside an explicit "},{"type":"text","text":"BEGIN","marks":[{"type":"code"}]},{"type":"text","text":", most engines run in "},{"type":"text","text":"autocommit","marks":[{"type":"bold"}]},{"type":"text","text":" mode: every statement is its own transaction. Oracle is the exception — a transaction starts implicitly and you must "},{"type":"text","text":"COMMIT","marks":[{"type":"code"}]},{"type":"text","text":". Python''s DB-API and many drivers open transactions for you and require "},{"type":"text","text":"conn.commit()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"8a50712a-533c-7c20-bb74-31ed6707b62e","type":"callout","position":"aI","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep transactions short: do the reads and computation first, then "},{"type":"text","text":"BEGIN","marks":[{"type":"code"}]},{"type":"text","text":" → writes → "},{"type":"text","text":"COMMIT","marks":[{"type":"code"}]},{"type":"text","text":". Long transactions hold locks, block other users and bloat MVCC history."}]}]}},"revision":1},{"id":"d392c7d6-dace-707b-8591-35cd23726527","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain ACID with a bank transfer."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Atomicity","marks":[{"type":"bold"}]},{"type":"text","text":": debit and credit both apply or neither does. "},{"type":"text","text":"Consistency","marks":[{"type":"bold"}]},{"type":"text","text":": balances never go negative and total money is preserved (constraints). "},{"type":"text","text":"Isolation","marks":[{"type":"bold"}]},{"type":"text","text":": a concurrent report never sees money “in flight” (debited but not yet credited). "},{"type":"text","text":"Durability","marks":[{"type":"bold"}]},{"type":"text","text":": once the user sees “transfer complete”, a crash can''t undo it."}]}]}},"revision":1},{"id":"7f9f39a9-4661-76a1-84a3-c4acca8c3b55","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between COMMIT and ROLLBACK?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"COMMIT","marks":[{"type":"code"}]},{"type":"text","text":" makes all changes of the transaction permanent and visible to others. "},{"type":"text","text":"ROLLBACK","marks":[{"type":"code"}]},{"type":"text","text":" discards them, restoring the state at "},{"type":"text","text":"BEGIN","marks":[{"type":"code"}]},{"type":"text","text":" (or at a "},{"type":"text","text":"SAVEPOINT","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"ROLLBACK TO","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
