SELECT 'a8446494-4095-7e39-8e56-e525454ac685', 'f432a3ee-e425-7840-9ada-32af01091716', 1, 'PUBLISHED', 'Triggers', '[{"id":"de97e1df-56c4-70c0-833e-82f4e912484c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A trigger is code the database runs "},{"type":"text","text":"automatically","marks":[{"type":"bold"}]},{"type":"text","text":" before or after an "},{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"DELETE","marks":[{"type":"code"}]},{"type":"text","text":" on a table — for audit logs, derived columns and integrity rules."}]}]}},"revision":1},{"id":"517bd0a7-3ed7-7d23-a562-1df7dc831e8e","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Part"}],[{"type":"text","text":"Options"}]],[[{"type":"text","text":"Timing"}],[{"type":"text","text":"BEFORE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"AFTER","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"INSTEAD OF","marks":[{"type":"code"}]},{"type":"text","text":" (views)"}]],[[{"type":"text","text":"Event"}],[{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"UPDATE [OF col]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"DELETE","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Granularity"}],[{"type":"text","text":"FOR EACH ROW","marks":[{"type":"code"}]},{"type":"text","text":" (row-level) or per statement (PostgreSQL, SQL Server)"}]],[[{"type":"text","text":"Row values"}],[{"type":"text","text":"NEW.col","marks":[{"type":"code"}]},{"type":"text","text":" (insert/update), "},{"type":"text","text":"OLD.col","marks":[{"type":"code"}]},{"type":"text","text":" (update/delete); SQL Server uses "},{"type":"text","text":"inserted","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"deleted","marks":[{"type":"code"}]},{"type":"text","text":" tables"}]]]},"revision":1},{"id":"2fa3faec-a710-7df9-8dcf-30f28a8ebd2e","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Audit log with AFTER UPDATE"}]},"revision":1},{"id":"f1fdc866-f06d-700d-85d5-12da3b583dd5","type":"code","position":"a3","content":{"language":"sql","code":"CREATE TABLE salary_audit (\n    emp_id     INTEGER,\n    old_salary INTEGER,\n    new_salary INTEGER,\n    changed_at TEXT DEFAULT ''2024-06-01''\n);\n\nCREATE TRIGGER trg_salary_audit\nAFTER UPDATE OF salary ON employees\nFOR EACH ROW\nWHEN NEW.salary <> OLD.salary\nBEGIN\n    INSERT INTO salary_audit (emp_id, old_salary, new_salary)\n    VALUES (OLD.emp_id, OLD.salary, NEW.salary);\nEND;\n\nUPDATE employees SET salary = salary + 5000 WHERE dept_id = 3;\nUPDATE employees SET name = ''Sara K'' WHERE emp_id = 9;       -- salary not touched: no audit row\n\nSELECT * FROM salary_audit ORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"660d1c16-8c35-7d73-a750-fd812c475aad","type":"code","position":"a4","content":{"language":"text","code":"emp_id | old_salary | new_salary | changed_at\n-------+------------+------------+-----------\n8      | 80000      | 85000      | 2024-06-01\n9      | 85000      | 90000      | 2024-06-01","filename":"Output"},"revision":1},{"id":"1a381083-5b1b-7b09-a141-6f77694342b2","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Validation with BEFORE + RAISE"}]},"revision":1},{"id":"59d007c1-f4dc-7961-86f2-a57b83e5083e","type":"code","position":"a6","content":{"language":"sql","code":"CREATE TRIGGER trg_no_big_cut\nBEFORE UPDATE OF salary ON employees\nFOR EACH ROW\nWHEN NEW.salary < OLD.salary * 0.8\nBEGIN\n    SELECT RAISE(ABORT, ''salary cut above 20% not allowed'');\nEND;\n\nUPDATE employees SET salary = 50000 WHERE emp_id = 2;","filename":"SQL"},"revision":1},{"id":"1d35c007-8462-7ea9-8644-140fa87ef02c","type":"code","position":"a7","content":{"language":"text","code":"salary cut above 20% not allowed","filename":"Error"},"revision":1},{"id":"340da3c6-29dc-703a-8b38-09f922442d89","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Maintaining a derived value"}]},"revision":1},{"id":"395e6734-b4d3-75d3-bd60-8b6ac19f48d1","type":"code","position":"a9","content":{"language":"sql","code":"ALTER TABLE products ADD COLUMN units_sold INTEGER NOT NULL DEFAULT 0;\nUPDATE products SET units_sold = (SELECT COALESCE(SUM(quantity), 0) FROM order_items oi\n                                  WHERE oi.product_id = products.product_id);\n\nCREATE TRIGGER trg_units_sold\nAFTER INSERT ON order_items\nFOR EACH ROW\nBEGIN\n    UPDATE products SET units_sold = units_sold + NEW.quantity\n    WHERE product_id = NEW.product_id;\nEND;\n\nINSERT INTO orders VALUES (109, 5, ''2024-03-20'', ''pending'');\nINSERT INTO order_items VALUES (109, 7, 2, 12000), (109, 6, 3, 20);\n\nSELECT name, units_sold FROM products WHERE product_id IN (6, 7) ORDER BY product_id;","filename":"SQL"},"revision":1},{"id":"def0f379-38ad-7a1a-9328-ae5fc7dcce54","type":"code","position":"aA","content":{"language":"text","code":"name    | units_sold\n--------+-----------\nPen     | 18\nMonitor | 2","filename":"Output"},"revision":1},{"id":"f6ebf6c2-8af7-738b-8bfd-23d52dd5ddaf","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"INSTEAD OF: making a view writable"}]},"revision":1},{"id":"57796053-770c-7918-bd76-689da058c3ec","type":"code","position":"aC","content":{"language":"sql","code":"CREATE VIEW emp_public AS SELECT emp_id, name, dept_id FROM employees;\n\nCREATE TRIGGER trg_emp_public_insert\nINSTEAD OF INSERT ON emp_public\nBEGIN\n    INSERT INTO employees (emp_id, name, dept_id, salary, hire_date)\n    VALUES (NEW.emp_id, NEW.name, NEW.dept_id, 50000, ''2024-06-01'');\nEND;\n\nINSERT INTO emp_public VALUES (11, ''Tara'', 4);\nSELECT emp_id, name, dept_id, salary FROM employees WHERE emp_id = 11;","filename":"SQL"},"revision":1},{"id":"a27de976-5ff8-7fc1-ab64-77db4585b89e","type":"code","position":"aD","content":{"language":"text","code":"emp_id | name | dept_id | salary\n-------+------+---------+-------\n11     | Tara | 4       | 50000","filename":"Output"},"revision":1},{"id":"3ec8bac1-4c33-71da-b3de-58d9015e47c0","type":"code","position":"aE","content":{"language":"sql","code":"-- PostgreSQL: the trigger body is a function\nCREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n    NEW.updated_at := now();\n    RETURN NEW;\nEND $$;\n\nCREATE TRIGGER trg_touch BEFORE UPDATE ON customers\nFOR EACH ROW EXECUTE FUNCTION set_updated_at();","filename":"PostgreSQL"},"revision":1},{"id":"82f4c1aa-717a-7e0a-9108-a01ccaf28b13","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Triggers are invisible side effects: a simple "},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" can fan out into cascades of hidden writes, slow bulk loads and surprise developers. Keep them small, document them, and prefer constraints for pure integrity rules."}]}]}},"revision":1},{"id":"33c77f95-0b8e-7d1d-91d5-d5956771fcbf","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are triggers used for, and what are their drawbacks?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Audit trails, keeping denormalised/derived columns in sync, enforcing complex rules constraints can''t express, and making views writable. Drawbacks: hidden logic, harder debugging, performance cost on every write (especially row-level triggers on bulk operations), and possible trigger chains."}]}]}},"revision":1},{"id":"08b0b698-4bb7-76d8-89e7-2e2aed19b1a0","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BEFORE vs AFTER trigger?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BEFORE","marks":[{"type":"code"}]},{"type":"text","text":" runs before the row is written — use it to validate or modify "},{"type":"text","text":"NEW","marks":[{"type":"code"}]},{"type":"text","text":" values (or reject the change). "},{"type":"text","text":"AFTER","marks":[{"type":"code"}]},{"type":"text","text":" runs once the change is applied — use it for side effects like audit rows or updating other tables, when the final values are known."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
