SELECT '117eed88-fb85-7eed-97c7-d4ca5e02bc43', 'c7e502d9-c470-7cf6-95a7-65fa7b523731', 1, 'PUBLISHED', 'UPDATE & DELETE', '[{"id":"2234a2f3-8d01-720e-91fa-e11cea5e146e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" changes column values in existing rows; "},{"type":"text","text":"DELETE","marks":[{"type":"code"}]},{"type":"text","text":" removes rows. Both touch "},{"type":"text","text":"every row the ","marks":[{"type":"bold"}]},{"type":"text","text":"WHERE","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" matches","marks":[{"type":"bold"}]},{"type":"text","text":" — which is all of them if you forget it."}]}]}},"revision":1},{"id":"d9e12c5e-b871-7ea6-9c34-e0a1181066b0","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"UPDATE"}]},"revision":1},{"id":"38e18822-6df9-7681-b6ae-9e163a88f887","type":"code","position":"a2","content":{"language":"sql","code":"-- 10% raise for Sales; several columns can change at once\nUPDATE employees\nSET salary = salary * 1.10,\n    email  = COALESCE(email, lower(name) || ''@corp.in'')\nWHERE dept_id = 2;\n\nSELECT emp_id, name, email, salary FROM employees WHERE dept_id = 2 ORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"6f5ae313-1cc9-7e9f-8ebc-c572180cdcfd","type":"code","position":"a3","content":{"language":"text","code":"emp_id | name  | email         | salary\n-------+-------+---------------+-------------------\n5      | Priya | priya@corp.in | 121000.00000000001\n6      | Arjun | arjun@corp.in | 77000\n7      | Neha  | neha@corp.in  | 79200","filename":"Output"},"revision":1},{"id":"ba07c901-113a-7257-b6b8-333debf52bdf","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every expression on the right of "},{"type":"text","text":"SET","marks":[{"type":"code"}]},{"type":"text","text":" sees the row''s "},{"type":"text","text":"old","marks":[{"type":"bold"}]},{"type":"text","text":" values, so "},{"type":"text","text":"SET a = b, b = a","marks":[{"type":"code"}]},{"type":"text","text":" swaps two columns in standard SQL (MySQL is the odd one out — it applies assignments left to right)."}]}]}},"revision":1},{"id":"4d4726ce-e9ab-78e9-b652-3afcd648b499","type":"callout","position":"a5","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Priya''s "},{"type":"text","text":"121000.00000000001","marks":[{"type":"code"}]},{"type":"text","text":" is floating-point error from "},{"type":"text","text":"* 1.10","marks":[{"type":"code"}]},{"type":"text","text":" (SQLite stored a "},{"type":"text","text":"REAL","marks":[{"type":"code"}]},{"type":"text","text":"). In a real schema "},{"type":"text","text":"salary","marks":[{"type":"code"}]},{"type":"text","text":" would be "},{"type":"text","text":"DECIMAL(10,2)","marks":[{"type":"code"}]},{"type":"text","text":"; in SQLite wrap it: "},{"type":"text","text":"CAST(round(salary * 1.10) AS INTEGER)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"67f16810-eeeb-7b79-95d7-54acdbca02b4","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"UPDATE using another table"}]},"revision":1},{"id":"89741b1f-6d69-7ced-b67f-0339edbab33d","type":"code","position":"a7","content":{"language":"sql","code":"-- raise everyone located in Hyderabad by 5000: subquery form (works everywhere)\nUPDATE employees\nSET salary = salary + 5000\nWHERE dept_id IN (SELECT dept_id FROM departments WHERE location = ''Hyderabad'');\n\nSELECT name, salary FROM employees WHERE dept_id = 3 ORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"e3e20a5e-da06-79c1-9c64-0f656a7ac4e9","type":"code","position":"a8","content":{"language":"text","code":"name   | salary\n-------+-------\nVikram | 85000\nSara   | 90000","filename":"Output"},"revision":1},{"id":"5845ce1c-a244-7dcf-8562-c54e15d9763f","type":"code","position":"a9","content":{"language":"sql","code":"-- UPDATE … FROM (PostgreSQL, SQLite 3.33+): join the table being updated\nCREATE TABLE raises (emp_id INTEGER PRIMARY KEY, pct INTEGER);\nINSERT INTO raises VALUES (3, 10), (4, 20);\n\nUPDATE employees\nSET salary = salary + salary * r.pct / 100\nFROM raises AS r\nWHERE r.emp_id = employees.emp_id;\n\nSELECT name, salary FROM employees WHERE emp_id IN (3, 4) ORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"d1a8ea8d-ee31-77d3-b8ef-9e8e6d104c9f","type":"code","position":"aA","content":{"language":"text","code":"name  | salary\n------+-------\nMeera | 104500\nKaran | 114000","filename":"Output"},"revision":1},{"id":"d471d8a8-3be6-703b-921c-b2283de7894c","type":"code","position":"aB","content":{"language":"sql","code":"-- MySQL: multi-table UPDATE with JOIN\nUPDATE employees e\nJOIN raises r ON r.emp_id = e.emp_id\nSET e.salary = e.salary + e.salary * r.pct / 100;\n\n-- SQL Server: UPDATE … FROM with an alias\nUPDATE e SET e.salary = e.salary + e.salary * r.pct / 100\nFROM employees e JOIN raises r ON r.emp_id = e.emp_id;","filename":"MySQL / SQL Server"},"revision":1},{"id":"8b98e674-5013-7876-aeda-ced44d6615cb","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"DELETE"}]},"revision":1},{"id":"660b1f40-0e98-7f70-a7e0-1afaeb2eba1c","type":"code","position":"aD","content":{"language":"sql","code":"-- remove order lines of cancelled orders, then the orders themselves\nDELETE FROM order_items\nWHERE order_id IN (SELECT order_id FROM orders WHERE status = ''cancelled'');\n\nDELETE FROM orders WHERE status = ''cancelled''\nRETURNING order_id, customer_id;\n\nSELECT COUNT(*) AS orders_left FROM orders;","filename":"SQL"},"revision":1},{"id":"7c3eced1-f795-7355-a829-07aca7e7f4af","type":"code","position":"aE","content":{"language":"text","code":"order_id | customer_id\n---------+------------\n105      | 4\n\norders_left\n-----------\n7","filename":"Output"},"revision":1},{"id":"ade028e5-aec9-79d1-95ac-11a52618d9ef","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The child rows ("},{"type":"text","text":"order_items","marks":[{"type":"code"}]},{"type":"text","text":") had to go first — otherwise the foreign key would block deleting the order (unless it was declared "},{"type":"text","text":"ON DELETE CASCADE","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"33b02420-4486-7b78-9bd7-351cb27c5abc","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Safe habits"}]},"revision":1},{"id":"0ec8c93d-6307-7fb2-aff2-797b7438f966","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Preview","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Run "},{"type":"text","text":"SELECT … WHERE <same condition>","marks":[{"type":"code"}]},{"type":"text","text":" first and check the row count."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wrap in a transaction","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"BEGIN; UPDATE …;","marks":[{"type":"code"}]},{"type":"text","text":" → check the result → "},{"type":"text","text":"COMMIT","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"ROLLBACK","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Limit the blast radius","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Key the "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" on the primary key when you mean one row."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer soft deletes for business data","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"UPDATE … SET deleted_at = CURRENT_TIMESTAMP","marks":[{"type":"code"}]},{"type":"text","text":" keeps history and is reversible."}]}]}]}]}},"revision":1},{"id":"bc0925fb-96de-7a3d-a64f-bbd1556e0835","type":"code","position":"aI","content":{"language":"sql","code":"BEGIN;\nUPDATE employees SET salary = 1;          -- oops: no WHERE, all 10 rows changed\nSELECT COUNT(*) AS paid_one_rupee FROM employees WHERE salary = 1;\nROLLBACK;                                 -- undo everything since BEGIN\nSELECT name, salary FROM employees WHERE emp_id = 1;","filename":"SQL"},"revision":1},{"id":"9cfa2b36-da92-7852-9da7-30cc05af8be8","type":"code","position":"aJ","content":{"language":"text","code":"paid_one_rupee\n--------------\n10\n\nname | salary\n-----+-------\nAsha | 150000","filename":"Output"},"revision":1},{"id":"32ec8ccf-8ce8-7675-91a4-131053093121","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you delete rows from one table based on another table?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a subquery — "},{"type":"text","text":"DELETE FROM a WHERE id IN (SELECT a_id FROM b WHERE …)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"WHERE EXISTS (SELECT 1 FROM b WHERE b.a_id = a.id …)","marks":[{"type":"code"}]},{"type":"text","text":". MySQL and SQL Server also allow a join form: "},{"type":"text","text":"DELETE a FROM a JOIN b ON … WHERE …","marks":[{"type":"code"}]},{"type":"text","text":"; PostgreSQL has "},{"type":"text","text":"DELETE FROM a USING b WHERE …","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"399a8596-5943-7fa1-a7a3-21eeb08c010b","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens if you run UPDATE without WHERE?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every row in the table is updated. If you are inside an explicit transaction you can "},{"type":"text","text":"ROLLBACK","marks":[{"type":"code"}]},{"type":"text","text":"; in autocommit mode the change is permanent and you need a backup or point-in-time recovery. MySQL''s "},{"type":"text","text":"--safe-updates","marks":[{"type":"code"}]},{"type":"text","text":" mode refuses "},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"DELETE","marks":[{"type":"code"}]},{"type":"text","text":" without a key-based "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"LIMIT","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
