INSERT INTO "notes"."NoteSearchDocument" ("noteId", "versionId", "title", "topics", "body", "document", "updatedAt")
SELECT 'c7e502d9-c470-7cf6-95a7-65fa7b523731', '117eed88-fb85-7eed-97c7-d4ca5e02bc43', 'UPDATE & DELETE', 'UPDATE & DELETE', 'UPDATE changes column values in existing rows; DELETE removes rows. Both touch every row the WHERE matches — which is all of them if you forget it.
UPDATE
-- 10% raise for Sales; several columns can change at once
UPDATE employees
SET salary = salary * 1.10,
    email  = COALESCE(email, lower(name) || ''@corp.in'')
WHERE dept_id = 2;

SELECT emp_id, name, email, salary FROM employees WHERE dept_id = 2 ORDER BY emp_id;
emp_id | name  | email         | salary
-------+-------+---------------+-------------------
5      | Priya | priya@corp.in | 121000.00000000001
6      | Arjun | arjun@corp.in | 77000
7      | Neha  | neha@corp.in  | 79200
Key point
Every expression on the right of SET sees the row''s old values, so SET a = b, b = a swaps two columns in standard SQL (MySQL is the odd one out — it applies assignments left to right).
Watch out
Priya''s 121000.00000000001 is floating-point error from * 1.10 (SQLite stored a REAL). In a real schema salary would be DECIMAL(10,2); in SQLite wrap it: CAST(round(salary * 1.10) AS INTEGER).
UPDATE using another table
-- raise everyone located in Hyderabad by 5000: subquery form (works everywhere)
UPDATE employees
SET salary = salary + 5000
