e":"bold"}]},{"type":"text","text":" the old row and inserts a new one — columns you did not supply fall back to defaults."}]}]}},"revision":1},{"id":"2bfdbb68-ce8a-7ee7-9dfc-e27eb3668caa","type":"code","position":"aA","content":{"language":"sql","code":"CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, plan TEXT DEFAULT ''free'');\nINSERT INTO users VALUES (1, ''Asha'', ''premium'');\n\nINSERT OR REPLACE INTO users (id, name) VALUES (1, ''Asha R'');   -- plan is lost!\nSELECT * FROM users;","filename":"SQL"},"revision":1},{"id":"e8f706a5-f7c5-735e-bf5f-7236c163f56a","type":"code","position":"aB","content":{"language":"text","code":"id | name   | plan\n---+--------+-----\n1  | Asha R | free","filename":"Output"},"revision":1},{"id":"37ce5d85-8bea-77ae-9bb9-27c53229b663","type":"callout","position":"aC","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"REPLACE","marks":[{"type":"code"}]},{"type":"text","text":" also fires delete triggers and can cascade-delete child rows. Prefer "},{"type":"text","text":"ON CONFLICT … DO UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"ON DUPLICATE KEY UPDATE","marks":[{"type":"code"}]},{"type":"text","text":", which update in place."}]}]}},"revision":1},{"id":"ffaa9295-c23b-79c1-9d0a-106ff98faa2c","type":"callout","position":"aD","content":{"variant":"warning","title":"Race condition","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"“"},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":"” in application code is a race: two requests can both see “not found” and both insert. Upsert statements (or a unique constraint plus retry) make it atomic."}]}]}},"revision":1},{"id