SELECT '449d3d6e-d00c-794c-9a60-4453f73dae81', 'e46679c1-82c5-769e-9df7-6480286a7309', 1, 'PUBLISHED', 'Views', '[{"id":"b058e33b-846d-7c90-ae1e-8483c3201179","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A view is a "},{"type":"text","text":"saved query","marks":[{"type":"bold"}]},{"type":"text","text":" that behaves like a table. It stores no data (unless materialised) — every time you select from it, its query runs."}]}]}},"revision":1},{"id":"fc9ae8c1-92b2-7527-8d6c-33e65eeba29a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Creating and using a view"}]},"revision":1},{"id":"fdf27637-debd-7d5b-ae21-0ecb3dd3d8f2","type":"code","position":"a2","content":{"language":"sql","code":"CREATE VIEW employee_directory AS\nSELECT e.emp_id, e.name, d.name AS department, d.location, m.name AS manager\nFROM employees e\nLEFT JOIN departments d ON d.dept_id = e.dept_id\nLEFT JOIN employees  m ON m.emp_id  = e.manager_id;\n\nSELECT name, department, manager\nFROM employee_directory\nWHERE location = ''Mumbai''\nORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"0a8e6afe-26ac-766e-bcf3-c26535530641","type":"code","position":"a3","content":{"language":"text","code":"name  | department | manager\n------+------------+--------\nPriya | Sales      | Asha\nArjun | Sales      | Priya\nNeha  | Sales      | Priya","filename":"Output"},"revision":1},{"id":"9eef6779-5ba5-793e-9a22-f40d80ab4903","type":"callout","position":"a4","content":{"variant":"note","title":"Simplicity","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hide complex joins behind a simple name; analysts query "},{"type":"text","text":"employee_directory","marks":[{"type":"code"}]},{"type":"text","text":", not four joins."}]}]}},"revision":1},{"id":"eb47f53d-1972-75fd-821d-2f33e5a8d440","type":"callout","position":"a5","content":{"variant":"note","title":"Security","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grant access to a view that exposes some columns/rows (no "},{"type":"text","text":"salary","marks":[{"type":"code"}]},{"type":"text","text":") instead of the base table."}]}]}},"revision":1},{"id":"c5021b07-f3c8-7a51-b801-4a70f1a2e4b1","type":"callout","position":"a6","content":{"variant":"note","title":"Stable interface","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Refactor the underlying tables while the view keeps the old shape for existing reports."}]}]}},"revision":1},{"id":"2ee5b21d-d49b-783f-97aa-0df3653949a0","type":"callout","position":"a7","content":{"variant":"note","title":"Consistency","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One definition of “active customer” or “net revenue” instead of ten copies."}]}]}},"revision":1},{"id":"dbc48cd2-416e-7b96-861d-b083d9649014","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"A view for business logic"}]},"revision":1},{"id":"e4c6bd83-fdcf-70e5-9b73-bedccdae25a1","type":"code","position":"a9","content":{"language":"sql","code":"CREATE VIEW order_summary AS\nSELECT o.order_id, o.customer_id, o.order_date, o.status,\n       SUM(oi.quantity * oi.unit_price) AS order_total,\n       COUNT(*) AS line_count\nFROM orders o JOIN order_items oi ON oi.order_id = o.order_id\nGROUP BY o.order_id, o.customer_id, o.order_date, o.status;\n\nSELECT status, COUNT(*) AS orders, SUM(order_total) AS value\nFROM order_summary\nGROUP BY status\nORDER BY value DESC;","filename":"SQL"},"revision":1},{"id":"a33feb52-8500-7202-83cb-86faeda4d09c","type":"code","position":"aA","content":{"language":"text","code":"status    | orders | value\n----------+--------+-------\ndelivered | 4      | 119100\nshipped   | 2      | 23000\ncancelled | 1      | 5000\npending   | 1      | 1200","filename":"Output"},"revision":1},{"id":"40443b94-8076-7978-82f6-1060a462dcf7","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Updatable views"}]},"revision":1},{"id":"0e0da127-f846-701d-b322-6fb0833a21f9","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A simple view over "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" table without aggregates, "},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" is usually updatable in PostgreSQL, MySQL, SQL Server and Oracle. "},{"type":"text","text":"WITH CHECK OPTION","marks":[{"type":"code"}]},{"type":"text","text":" rejects writes that would fall outside the view''s "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c8211bbd-b69d-7a13-bade-b53aa739e6e3","type":"code","position":"aD","content":{"language":"sql","code":"CREATE VIEW sales_team AS\nSELECT emp_id, name, salary, dept_id FROM employees WHERE dept_id = 2\nWITH CHECK OPTION;\n\nUPDATE sales_team SET salary = salary + 1000 WHERE emp_id = 6;   -- OK: updates employees\nUPDATE sales_team SET dept_id = 3 WHERE emp_id = 6;              -- ERROR: row would leave the view","filename":"PostgreSQL / MySQL / SQL Server / Oracle"},"revision":1},{"id":"8d2679d3-1675-7d67-b660-582fff642c5a","type":"callout","position":"aE","content":{"variant":"note","title":"SQLite","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SQLite views are read-only; you make them writable with "},{"type":"text","text":"INSTEAD OF","marks":[{"type":"code"}]},{"type":"text","text":" triggers (see Triggers)."}]}]}},"revision":1},{"id":"ff779462-cdca-7517-916e-bd0fa6ae1b22","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Materialised views"}]},"revision":1},{"id":"8f0fe467-b5b7-7831-bcec-220c9ed9d56f","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"materialised view","marks":[{"type":"bold"}]},{"type":"text","text":" stores the query result physically, so reads are fast but data is only as fresh as the last refresh. Great for heavy dashboards."}]}]}},"revision":1},{"id":"d5591894-c86b-7ac6-9d5e-8dfc517ede3a","type":"code","position":"aH","content":{"language":"sql","code":"CREATE MATERIALIZED VIEW monthly_revenue AS\nSELECT date_trunc(''month'', order_date) AS month, SUM(total) AS revenue\nFROM order_summary GROUP BY 1;\n\nREFRESH MATERIALIZED VIEW CONCURRENTLY monthly_revenue;   -- needs a unique index","filename":"PostgreSQL (Oracle: MATERIALIZED VIEW; SQL Server: indexed views)"},"revision":1},{"id":"cbd768ef-56dd-7a30-8ca0-d566a91662a3","type":"table","position":"aI","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"View"}],[{"type":"text","text":"Materialised view"}]],[[{"type":"text","text":"Stores data"}],[{"type":"text","text":"No — query runs on every read"}],[{"type":"text","text":"Yes — a snapshot"}]],[[{"type":"text","text":"Freshness"}],[{"type":"text","text":"Always current"}],[{"type":"text","text":"Stale until refreshed"}]],[[{"type":"text","text":"Read speed"}],[{"type":"text","text":"Same as the underlying query"}],[{"type":"text","text":"Fast (can be indexed)"}]],[[{"type":"text","text":"Write cost"}],[{"type":"text","text":"None"}],[{"type":"text","text":"Refresh cost"}]]]},"revision":1},{"id":"90472548-2300-7f12-85bf-ab76177cc0f2","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a view and a table?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A table stores rows. A (regular) view stores only a query; reading it runs the query against the base tables, so it is always up to date and uses no extra storage. Views give abstraction and security; they don''t make queries faster by themselves."}]}]}},"revision":1},{"id":"6c881ea4-d431-75c4-9599-9ad2aa8f8485","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can you insert into a view?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If the view is "},{"type":"text","text":"updatable","marks":[{"type":"italic"}]},{"type":"text","text":" — typically a single base table, no aggregates/"},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":"/set operators, and it includes all "},{"type":"text","text":"NOT NULL","marks":[{"type":"code"}]},{"type":"text","text":" columns without defaults. Otherwise, use "},{"type":"text","text":"INSTEAD OF","marks":[{"type":"code"}]},{"type":"text","text":" triggers (SQL Server, Oracle, PostgreSQL, SQLite)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
