SELECT 'e86e7986-37cd-796a-9a2e-e6806c1467f5', '777144ec-c9f8-7443-9de0-ab182aaaa7ee', 1, 'PUBLISHED', 'Filtering with WHERE', '[{"id":"7f4a01f0-f904-725b-8e1f-f2e72434fb6a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" keeps only the rows for which a condition is "},{"type":"text","text":"true","marks":[{"type":"bold"}]},{"type":"text","text":" — rows where it is false "},{"type":"text","text":"or unknown","marks":[{"type":"italic"}]},{"type":"text","text":" ("},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":") are dropped."}]}]}},"revision":1},{"id":"278b8217-5ab0-7d4c-8864-237f25fee755","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Operators"}]},"revision":1},{"id":"6ac94a0c-1f33-7806-abac-cf23adcba6f4","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Kind"}],[{"type":"text","text":"Operators"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Comparison"}],[{"type":"text","text":"= <> != < <= > >=","marks":[{"type":"code"}]}],[{"type":"text","text":"salary >= 100000","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Logical"}],[{"type":"text","text":"AND","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"OR","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"NOT","marks":[{"type":"code"}]}],[{"type":"text","text":"dept_id = 1 AND salary > 100000","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Range"}],[{"type":"text","text":"BETWEEN a AND b","marks":[{"type":"code"}]},{"type":"text","text":" (inclusive)"}],[{"type":"text","text":"hire_date BETWEEN ''2018-01-01'' AND ''2020-12-31''","marks":[{"type":"code"}]}]],[[{"type":"text","text":"List"}],[{"type":"text","text":"IN (…)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"NOT IN (…)","marks":[{"type":"code"}]}],[{"type":"text","text":"dept_id IN (2, 3)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Pattern"}],[{"type":"text","text":"LIKE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"NOT LIKE","marks":[{"type":"code"}]}],[{"type":"text","text":"name LIKE ''A%''","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Null test"}],[{"type":"text","text":"IS NULL","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IS NOT NULL","marks":[{"type":"code"}]}],[{"type":"text","text":"email IS NULL","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"f5c52a33-aac8-718d-b289-34c947431862","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Comparison and logic"}]},"revision":1},{"id":"b55b0b4b-26f3-76f4-9bdc-e0e8ada1067d","type":"code","position":"a4","content":{"language":"sql","code":"SELECT name, dept_id, salary\nFROM employees\nWHERE dept_id = 1 AND salary < 100000\nORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"1b28f4cc-d206-7018-9ad1-08e21b87a790","type":"code","position":"a5","content":{"language":"text","code":"name  | dept_id | salary\n------+---------+-------\nMeera | 1       | 95000\nKaran | 1       | 95000","filename":"Output"},"revision":1},{"id":"7b79b385-0e66-7ceb-bab8-cc4558c52391","type":"code","position":"a6","content":{"language":"sql","code":"SELECT name, hire_date\nFROM employees\nWHERE hire_date BETWEEN ''2018-01-01'' AND ''2020-12-31''\nORDER BY hire_date;","filename":"SQL"},"revision":1},{"id":"1f7bc2db-e2c4-7f03-ae44-e900f4ef7e48","type":"code","position":"a7","content":{"language":"text","code":"name   | hire_date\n-------+-----------\nVikram | 2018-09-05\nMeera  | 2019-01-10\nKaran  | 2020-08-01","filename":"Output"},"revision":1},{"id":"36804bf7-8e14-7a21-afa9-f2a9f2f95855","type":"code","position":"a8","content":{"language":"sql","code":"SELECT name, dept_id\nFROM employees\nWHERE dept_id