  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '777144ec-c9f8-7443-9de0-ab182aaaa7ee' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'e86e7986-37cd-796a-9a2e-e6806c1467f5' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

