SELECT '81bf2232-ffc2-710c-9321-6c7ffce63d4d', 'e5c94587-2688-76ce-9e63-3b109980458b', 1, 'PUBLISHED', 'Running Totals & Window Frames', '[{"id":"24cabce4-f906-713a-8792-d6541a99317f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"frame","marks":[{"type":"bold"}]},{"type":"text","text":" decides which rows around the current row a window aggregate sees: everything so far (running total), the last 3 rows (moving average), or the whole partition."}]}]}},"revision":1},{"id":"d122162e-97c4-7715-8f5c-6fcdfed96ac1","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Frame syntax"}]},"revision":1},{"id":"0e3f75a1-29b1-7a3e-a9f6-155980d97fac","type":"code","position":"a2","content":{"language":"sql","code":"{ROWS | RANGE | GROUPS} BETWEEN <start> AND <end>\n\n-- <start>/<end>:  UNBOUNDED PRECEDING | n PRECEDING | CURRENT ROW | n FOLLOWING | UNBOUNDED FOLLOWING","filename":"SQL"},"revision":1},{"id":"a94173de-07cc-76ed-beba-3a0a0c343851","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"OVER (…)","marks":[{"type":"code"}]}],[{"type":"text","text":"Default frame"}]],[[{"type":"text","text":"No "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]}],[{"type":"text","text":"The whole partition"}]],[[{"type":"text","text":"With "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]}],[{"type":"text","text":"RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW","marks":[{"type":"code"}]},{"type":"text","text":" — start to current row "},{"type":"text","text":"including peers (ties)","marks":[{"type":"italic"}]}]]]},"revision":1},{"id":"cb593987-91ab-7957-8ce2-1861783cfe41","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Running total, moving average, centered window"}]},"revision":1},{"id":"55745e5c-727b-73d0-b706-e508511a6627","type":"code","position":"a5","content":{"language":"sql","code":"SELECT day, amount,\n       SUM(amount) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total,\n       ROUND(AVG(amount) OVER (ORDER BY day ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 1) AS moving_avg_3,\n       MAX(amount) OVER (ORDER BY day ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS max_neighbourhood\nFROM daily_sales\nORDER BY day;","filename":"SQL"},"revision":1},{"id":"7357ba2c-ba85-7568-b92e-47c81ab6463e","type":"code","position":"a6","content":{"language":"text","code":"day        | amount | running_total | moving_avg_3 | max_neighbourhood\n-----------+--------+---------------+--------------+------------------\n2024-03-01 | 120    | 120           | 120.0        | 120\n2024-03-02 | 80     | 200           | 100.0        | 150\n2024-03-03 | 150    | 350           | 116.7        | 150\n2024-03-04 | 90     | 440           | 106.7        | 200\n2024-03-05 | 200    | 640           | 146.7        | 200\n2024-03-06 | 60     | 700           | 116.7        | 200","filename":"Output"},"revision":1},{"id":"a5a7d04f-8d0f-7979-a72d-53f548fbb8e6","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The first two moving averages use fewer than 3 rows (there is nothing before day 1). Filter them out or show them as incomplete if that matters."}]}]}},"revision":1},{"id":"6d248713-5157-7cc4-bef5-25e6d4ecd7ff","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"ROWS vs RANGE: the ties trap"}]},"revision":1},{"id":"8b833c64-bbef-745c-b223-06da1a85bb15","type":"code","position":"a9","content":{"language":"sql","code":"SELECT name, salary,\n       SUM(salary) OVER (ORDER BY salary)                                         AS range_default,\n       SUM(salary) OVER (ORDER BY salary ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS rows_frame\nFROM employees\nWHERE dept_id = 1\nORDER BY salary, emp_id;","filename":"SQL"},"revision":1},{"id":"d4de07e1-17f6-758b-8b08-cc630f8866dd","type":"code","position":"aA","content":{"language":"text","code":"name  | salary | range_default | rows_frame\n------+--------+---------------+-----------\nMeera | 95000  | 190000        | 95000\nKaran | 95000  | 190000        | 190000\nRavi  | 120000 | 310000        | 310000\nAsha  | 150000 | 460000        | 460000","filename":"Output"},"revision":1},{"id":"ae3cc865-f219-7ffb-b9a1-438f33528354","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Meera and Karan both earn 95000, so with the default "},{"type":"text","text":"RANGE","marks":[{"type":"code"}]},{"type":"text","text":" frame they are "},{"type":"text","text":"peers","marks":[{"type":"italic"}]},{"type":"text","text":" and both see 190000. "},{"type":"text","text":"ROWS","marks":[{"type":"code"}]},{"type":"text","text":" counts physical rows: 95000 then 190000. For running totals, specify "},{"type":"text","text":"ROWS","marks":[{"type":"code"}]},{"type":"text","text":" (and a unique tie-breaker in "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"cf30ebb2-39ca-72c4-8b6c-8d87df5c6c16","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Running total per group, and a reset"}]},"revision":1},{"id":"5eb50c59-c83a-7806-9613-c066a29b77a4","type":"code","position":"aD","content":{"language":"sql","code":"SELECT customer_id, order_id, order_date,\n       COUNT(*) OVER (PARTITION BY customer_id ORDER BY order_date\n                      ROWS UNBOUNDED PRECEDING) AS nth_order_of_customer\nFROM orders\nORDER BY customer_id, order_date;","filename":"SQL"},"revision":1},{"id":"4d2881dc-0256-7d14-9bca-5255a4b46b32","type":"code","position":"aE","content":{"language":"text","code":"customer_id | order_id | order_date | nth_order_of_customer\n------------+----------+------------+----------------------\n1           | 101      | 2024-01-05 | 1\n1           | 103      | 2024-02-03 | 2\n1           | 108      | 2024-03-15 | 3\n2           | 102      | 2024-01-12 | 1\n2           | 106      | 2024-03-01 | 2\n3           | 104      | 2024-02-14 | 1\n3           | 107      | 2024-03-08 | 2\n4           | 105      | 2024-02-20 | 1","filename":"Output"},"revision":1},{"id":"d5007adc-d216-7696-bcf7-334e955b61ff","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Cumulative share (Pareto)"}]},"revision":1},{"id":"6b3a878b-6570-7d77-93f9-a30f02dbf538","type":"code","position":"aG","content":{"language":"sql","code":"WITH product_rev AS (\n    SELECT p.name, SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM order_items oi JOIN products p ON p.product_id = oi.product_id\n    GROUP BY p.product_id, p.name\n)\nSELECT name, revenue,\n       ROUND(100.0 * SUM(revenue) OVER (ORDER BY revenue DESC ROWS UNBOUNDED PRECEDING)\n             / SUM(revenue) OVER (), 1) AS cumulative_pct\nFROM product_rev\nORDER BY revenue DESC;","filename":"SQL"},"revision":1},{"id":"cac5a518-9252-7ab5-9c95-6b5f627d118c","type":"code","position":"aH","content":{"language":"text","code":"name       | revenue | cumulative_pct\n-----------+---------+---------------\nLaptop     | 107000  | 72.2\nDesk       | 16000   | 82.9\nChair      | 13500   | 92.0\nHeadphones | 10000   | 98.8\nNotebook   | 1500    | 99.8\nPen        | 300     | 100.0","filename":"Output"},"revision":1},{"id":"3ca2d9f8-a9cf-73fa-b6af-4dc8b12775dd","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you calculate a running total in SQL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SUM(amount) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)","marks":[{"type":"code"}]},{"type":"text","text":", adding "},{"type":"text","text":"PARTITION BY","marks":[{"type":"code"}]},{"type":"text","text":" to restart per group. Without window functions: a correlated subquery "},{"type":"text","text":"(SELECT SUM(amount) FROM t t2 WHERE t2.day <= t.day)","marks":[{"type":"code"}]},{"type":"text","text":" — O(n²)."}]}]}},"revision":1},{"id":"3e1ad52c-b455-7e8b-bcb1-cfce8e521d23","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between ROWS and RANGE?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ROWS","marks":[{"type":"code"}]},{"type":"text","text":" defines the frame by physical row count (2 PRECEDING = the two rows before). "},{"type":"text","text":"RANGE","marks":[{"type":"code"}]},{"type":"text","text":" defines it by value of the "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":" key, so all rows with the same key (peers) are included together — which is why the default frame gives tied rows the same running total."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
