SELECT 'a022f314-2fc6-76dc-8f2b-0a3654e258ef', 'ceebcbd9-225d-78bb-8984-caecee8a62cd', 1, 'PUBLISHED', 'Window Functions: The Basics', '[{"id":"cd053719-7a3c-7e19-a40f-2b35164bb3eb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A window function computes a value "},{"type":"text","text":"across a set of related rows","marks":[{"type":"bold"}]},{"type":"text","text":" — without collapsing them like "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" does. Each row keeps its identity and gains an aggregate, a rank or a neighbour''s value."}]}]}},"revision":1},{"id":"2bfd01f8-eaea-73fe-9203-e7521e9a1b85","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OVER clause","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"f(…) OVER (PARTITION BY … ORDER BY … frame)","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"PARTITION BY","marks":[{"type":"code"}]},{"type":"text","text":" splits rows into independent groups, "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":" orders rows inside each partition, the frame picks which rows around the current one are included."}]}]}},"revision":1},{"id":"1392fa86-7b8d-7fc2-b5bc-bff558ee0d2f","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"GROUP BY vs window"}]},"revision":1},{"id":"a12b875d-ff43-7e47-9aad-d6e28557e61f","type":"code","position":"a3","content":{"language":"sql","code":"-- GROUP BY: one row per department\nSELECT dept_id, AVG(salary) AS dept_avg\nFROM employees WHERE dept_id IN (2, 3)\nGROUP BY dept_id\nORDER BY dept_id;\n\n-- window: every employee kept, department average attached\nSELECT name, dept_id, salary,\n       AVG(salary) OVER (PARTITION BY dept_id) AS dept_avg,\n       salary - AVG(salary) OVER (PARTITION BY dept_id) AS diff\nFROM employees WHERE dept_id IN (2, 3)\nORDER BY dept_id, emp_id;","filename":"SQL"},"revision":1},{"id":"4b66f7de-dd7e-7542-9dc1-8674e6637a87","type":"code","position":"a4","content":{"language":"text","code":"dept_id | dept_avg\n--------+---------\n2       | 84000.0\n3       | 82500.0\n\nname   | dept_id | salary | dept_avg | diff\n-------+---------+--------+----------+---------\nPriya  | 2       | 110000 | 84000.0  | 26000.0\nArjun  | 2       | 70000  | 84000.0  | -14000.0\nNeha   | 2       | 72000  | 84000.0  | -12000.0\nVikram | 3       | 80000  | 82500.0  | -2500.0\nSara   | 3       | 85000  | 82500.0  | 2500.0","filename":"Output"},"revision":1},{"id":"86460cfd-8093-7711-9ccf-855afc7a6f2b","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Aggregates as window functions"}]},"revision":1},{"id":"79fc6404-4bb1-780b-a399-a9dcc15af464","type":"code","position":"a6","content":{"language":"sql","code":"SELECT name, dept_id, salary,\n       SUM(salary)   OVER ()                     AS company_payroll,\n       ROUND(100.0 * salary / SUM(salary) OVER (), 1) AS pct_of_company,\n       COUNT(*)      OVER (PARTITION BY dept_id) AS dept_size,\n       MAX(salary)   OVER (PARTITION BY dept_id) AS dept_max\nFROM employees\nWHERE dept_id IS NOT NULL\nORDER BY dept_id, salary DESC, emp_id;","filename":"SQL"},"revision":1},{"id":"b882e1f1-20b1-7d98-ac69-104a5ea766e7","type":"code","position":"a7","content":{"language":"text","code":"name   | dept_id | salary | company_payroll | pct_of_company | dept_size | dept_max\n-------+---------+--------+-----------------+----------------+-----------+---------\nAsha   | 1       | 150000 | 877000          | 17.1           | 4         | 150000\nRavi   | 1       | 120000 | 877000          | 13.7           | 4         | 150000\nMeera  | 1       | 95000  | 877000          | 10.8           | 4         | 150000\nKaran  | 1       | 95000  | 877000          | 10.8           | 4         | 150000\nPriya  | 2       | 110000 | 877000          | 12.5           | 3         | 110000\nNeha   | 2       | 72000  | 877000          | 8.2            | 3         | 110000\nArjun  | 2       | 70000  | 877000          | 8.0            | 3         | 110000\nSara   | 3       | 85000  | 877000          | 9.7            | 2         | 85000\nVikram | 3       | 80000  | 877000          | 9.1            | 2         | 85000","filename":"Output"},"revision":1},{"id":"ffeca64c-f2e1-738a-97c6-d91c863cf973","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OVER ()","marks":[{"type":"code"}]},{"type":"text","text":" with nothing inside = one window containing all rows (of the result after "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"c6465a58-fa2c-73f5-89b0-d1cdf2440681","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Adding ORDER BY makes it cumulative"}]},"revision":1},{"id":"6429a3d8-6eba-7b0c-b622-8d7eba25b3ce","type":"code","position":"aA","content":{"language":"sql","code":"SELECT day, amount,\n       SUM(amount) OVER (ORDER BY day)  AS running_total,\n       COUNT(*)    OVER (ORDER BY day)  AS days_so_far\nFROM daily_sales\nORDER BY day;","filename":"SQL"},"revision":1},{"id":"77f83bfb-d5fa-71df-a64d-8ef04c2f6c33","type":"code","position":"aB","content":{"language":"text","code":"day        | amount | running_total | days_so_far\n-----------+--------+---------------+------------\n2024-03-01 | 120    | 120           | 1\n2024-03-02 | 80     | 200           | 2\n2024-03-03 | 150    | 350           | 3\n2024-03-04 | 90     | 440           | 4\n2024-03-05 | 200    | 640           | 5\n2024-03-06 | 60     | 700           | 6","filename":"Output"},"revision":1},{"id":"c185ae1b-ce08-7547-8a04-534f62f312eb","type":"callout","position":"aC","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":" inside "},{"type":"text","text":"OVER","marks":[{"type":"code"}]},{"type":"text","text":", the default frame becomes “from the start of the partition up to the current row”, so "},{"type":"text","text":"SUM","marks":[{"type":"code"}]},{"type":"text","text":" turns into a running total. Details in "},{"type":"text","text":"Running Totals & Window Frames","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"fd91ac99-f6fe-746f-b333-f73e162c9852","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"The family"}]},"revision":1},{"id":"c30c8ae0-2c04-708a-abad-89650486978a","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Kind"}],[{"type":"text","text":"Functions"}]],[[{"type":"text","text":"Aggregate"}],[{"type":"text","text":"SUM","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"AVG","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"COUNT","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MIN","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MAX","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"OVER (…)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Ranking"}],[{"type":"text","text":"ROW_NUMBER","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"RANK","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"DENSE_RANK","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"NTILE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"PERCENT_RANK","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"CUME_DIST","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Offset / value"}],[{"type":"text","text":"LAG","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"LEAD","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"FIRST_VALUE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"LAST_VALUE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"NTH_VALUE","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"d8df024a-bf4a-70de-abca-5111ae2ff437","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Where you can use them"}]},"revision":1},{"id":"523f823f-d62d-7528-9ea3-7e42b91b508d","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Window functions are evaluated in the "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" step, so they are allowed only in "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":". To filter on one, compute it in a CTE/subquery first:"}]}]}},"revision":1},{"id":"230459c0-e3a7-7bd7-9817-4177daf6cd9d","type":"code","position":"aH","content":{"language":"sql","code":"SELECT name FROM employees\nWHERE salary > AVG(salary) OVER ();","filename":"SQL"},"revision":1},{"id":"4b7fbf99-9d81-7b02-ab7b-00585c44cd0d","type":"code","position":"aI","content":{"language":"text","code":"misuse of window function AVG()","filename":"Error"},"revision":1},{"id":"7e02984d-6f45-7f85-8117-96e73b2506bb","type":"code","position":"aJ","content":{"language":"sql","code":"WITH x AS (\n    SELECT name, salary, AVG(salary) OVER () AS avg_all FROM employees\n)\nSELECT name, salary FROM x WHERE salary > avg_all ORDER BY salary DESC, name;","filename":"SQL"},"revision":1},{"id":"85a114ac-62ff-76d4-a60e-d41b6aecff2d","type":"code","position":"aK","content":{"language":"text","code":"name  | salary\n------+-------\nAsha  | 150000\nRavi  | 120000\nPriya | 110000\nKaran | 95000\nMeera | 95000","filename":"Output"},"revision":1},{"id":"20a2a5d6-d90e-7214-8eb7-b9cb4ffbcf07","type":"code","position":"aL","content":{"language":"sql","code":"-- Snowflake / BigQuery / DuckDB / Databricks: filter on a window directly\nSELECT name, dept_id, salary\nFROM employees\nQUALIFY ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) = 1;","filename":"Snowflake / BigQuery / DuckDB (QUALIFY)"},"revision":1},{"id":"37978bec-f4b7-7fe1-ab3c-95a740e301e7","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between GROUP BY and a window function?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" collapses each group into one output row, so you lose row detail. A window function computes over a group (the partition) but returns a value on "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" row — so you can show each employee next to their department average, rank or running total."}]}]}},"revision":1},{"id":"0b798b65-0bd0-7339-ac71-33f0795e10c1","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is PARTITION BY?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The window equivalent of "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":": it splits rows into independent partitions, and the window function restarts for each one. Without it, the whole result set is a single partition."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
